using UnityEditor;using System;using System.IO;using System.Linq;using UnityEngine;
namespace Xinghai.MapEditor.Editor {public static class PackageProof {public static void Run(){try{Directory.CreateDirectory("../../release");var runtime=Directory.GetFiles("Assets/XinghaiMap/Runtime").Where(p=>!p.EndsWith(".meta")&&!p.EndsWith("ProofPlayer.cs")).Select(p=>p.Replace('\\','/'));var editor=new[]{"BakeWindow","MapBaker","BakeJournal","SourceReader","PlacementIdentity"}.Select(n=>"Assets/XinghaiMap/Editor/"+n+".cs");AssetDatabase.ExportPackage(runtime.Concat(editor).ToArray(),"../../release/星骸地图团结插件.unitypackage",ExportPackageOptions.Default);Debug.Log("XH_PACKAGE_PASS");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}}}
